var largestMerge = function(word1, word2) {
    let i = 0, j = 0;
    const n = word1.length, m = word2.length;
    const res = [];
    while (i < n && j < m) {
        if (word1.slice(i) >= word2.slice(j)) {
            res.push(word1[i++]);
        } else {
            res.push(word2[j++]);
        }
    }
    res.push(word1.slice(i));
    res.push(word2.slice(j));
    return res.join('');
};
